import heapq

def bellman_ford(graph, src):
    """
    :param graph: A dictionary representing the graph where the keys are vertices and the values are dictionaries
                  of the form {neighbour: weight}.
    :param src: The source vertex.
    :return: A dictionary containing the shortest distance from the source to each vertex, and a list of the
